// RabbitMQ header "consume.amqp.<name>" -> attribute "<name>", so it reaches Solace as JMS property <name>
def flowFile = session.get()
if (!flowFile) return
def prefix = 'consume.amqp.'
def headers = flowFile.getAttributes().findAll { it.key.startsWith(prefix) }
// Names with '$' (amqp$routingKey...) belong to NiFi, a header must not overwrite them.
flowFile = session.putAllAttributes(flowFile, headers.collectEntries { [it.key.substring(prefix.length()), it.value] }.findAll { !it.key.contains('$') })
flowFile = session.removeAllAttributes(flowFile, headers.keySet())
session.transfer(flowFile, REL_SUCCESS)

// Router R-01 (SWIM APAC EMS v4, Bảng 11, bản tối thiểu). One message in from q/vnm/vatm/dev/router/in,
// one or more copies out. Each copy gets the attributes "exchange" and "routingKey" for PublishAMQP.
def flowFile = session.get()
if (!flowFile) return

def X = 'x/vnm/vatm/dev/'
def MANDATORY = ['APAC_SOURCE', 'APAC_RECIPIENT_LIST', 'APAC_CATEGORY', 'APAC_CATEGORY_VERSION', 'APAC_MESSAGE_TYPE', 'APAC_TIMESTAMP']
def ROUTES = [VV_VATM: 'VV_VATM', VV_HVN: 'VV_HVN']             // recipient code -> VV_ROUTE; codes not starting VV_ go to GEMS
def COUNTRY = [VV: 'vnm', WS: 'sgp', VT: 'tha', RJ: 'jpn']       // ICAO prefix -> ISO country in the routing key
def ORGANISATION = [VATM: 'vatm', HVN: 'vna', CAAS: 'caas', AEROTHAI: 'aerothai']
def MAX_RECIPIENTS = 50
def gemsMode = context.getAllProperties().get('gems.mode') ?: 'header'

// The routing key comes from the broker, never from a header.
def key = flowFile.getAttribute('amqp$routingKey') ?: ''
// RabbitMQ headers arrive as attributes "consume.amqp.<name>"; give them back their own names. Names the Bridge
// uses itself (anything with '$', exchange, routingKey) and the headers only the Router may set are dropped.
def prefix = 'consume.amqp.'
def received = flowFile.getAttributes().findAll { it.key.startsWith(prefix) }
def headers = received.collectEntries { [it.key.substring(prefix.length()), it.value] }
        .findAll { !it.key.contains('$') && !(it.key in ['exchange', 'routingKey', 'VV_ROUTE', 'VV_DLX_REASON']) }
flowFile = session.removeAllAttributes(flowFile, received.keySet())
flowFile = session.putAllAttributes(flowFile, headers)

def stamp = (headers.APAC_TIMESTAMP ?: '') + ',VV_EEMS_IN:' + System.currentTimeMillis()
flowFile = session.putAttribute(flowFile, 'APAC_TIMESTAMP', stamp)

def copies = []      // [exchange, routing key, extra attributes]
def problems = []
try {
    def missing = MANDATORY.findAll { !headers[it] }
    def levels = key.split('\\.') as List
    // <ICAO prefix>_<organisation> -> [country, organisation] as they appear in a routing key
    def place = { String code ->
        def m = code =~ /^([A-Z]{2})_([A-Z0-9]{1,20})$/
        m.matches() && COUNTRY[m.group(1)] ? [COUNTRY[m.group(1)], ORGANISATION[m.group(2)] ?: m.group(2).toLowerCase()] : null
    }
    if (missing) {
        problems << 'missing header ' + missing.join(',')
    } else if (key.startsWith('t.')) {
        copies << [X + 'swim', key, [:]]
    } else if (!key.startsWith('tr.') || levels.size() < 6) {
        problems << 'routing key must be t.<...> or tr.<country>.<org>.<country>.<org>.<env>...: ' + key
    } else if (place(headers.APAC_SOURCE) != levels[1..2]) {
        problems << 'APAC_SOURCE ' + headers.APAC_SOURCE + ' does not match the sender in the routing key'   // also stops loops
    } else {
        def list = headers.APAC_RECIPIENT_LIST.split(',')*.trim().findAll { it }
        flowFile = session.putAttribute(flowFile, 'APAC_RECIPIENT_LIST', list.join(','))
        def recipients = list.findAll { it != headers.APAC_SOURCE }.unique()
        if (recipients.size() > MAX_RECIPIENTS) {
            problems << 'more than ' + MAX_RECIPIENTS + ' recipients'
            recipients = []
        }
        def keyFor = { String code -> (levels.take(3) + place(code) + levels.drop(5)).join('.') }
        def gems = []
        recipients.each { code ->
            if (!place(code) || (code.startsWith('VV_') && !ROUTES[code])) problems << 'unknown recipient ' + code
            else if (ROUTES[code]) copies << [X + 'route', keyFor(code), [VV_ROUTE: ROUTES[code]]]
            else gems << code
        }
        if (gems && gemsMode == 'topic') gems.each { copies << [X + 'route', keyFor(it), [VV_ROUTE: 'GEMS']] }
        else if (gems) copies << [X + 'route', key, [VV_ROUTE: 'GEMS']]
        if (!copies && !problems) problems << 'no recipient other than the source'
    }
    def tooLong = copies.findAll { it[1].getBytes('UTF-8').length > 255 }
    if (tooLong) {
        problems << 'routing key longer than 255 bytes'
        copies -= tooLong
    }
} catch (Exception e) {
    copies = []
    problems << 'router error: ' + e
}

def out = stamp + ',VV_EEMS_OUT:' + System.currentTimeMillis()
copies.each { exchange, routingKey, extra ->
    def copy = session.clone(flowFile)
    copy = session.putAllAttributes(copy, extra + [APAC_TIMESTAMP: out, exchange: exchange, routingKey: routingKey])
    session.transfer(copy, REL_SUCCESS)
}
if (problems) {
    def reason = problems.join('; ')
    def dead = session.clone(flowFile)
    dead = session.putAllAttributes(dead, [VV_DLX_REASON: reason.take(500), exchange: X + 'dlx', routingKey: key.take(255)])
    session.transfer(dead, REL_SUCCESS)
}
session.remove(flowFile)
